# Lote 06: posições 46 a 53 do A1 (Find the Exit ... at + hora).
# TROCAS DE OBRA: pos 47: de The House That Jack Built (repetida do pos 46) para Finding Nemo
# TROCAS DE OBRA: pos 53: de My Grandfather's Clock (repetida do pos 52) para Cinderella
# TROCAS DE OBRA: pos 48: mantida The Great Gatsby; pos 49 Wynken, Blynken, and Nod; pos 50 The Simpsons; pos 51 Hickory Dickory Dock.


def P(*rows):
    return [list(r) for r in rows]


def Q(q, pt, opts, a, line, why):
    return dict(q=q, pt=pt, opts=[o.split('|', 1) for o in opts], a=a, line=line, why=why)


def H(e, x, y, en, pt, say, sayPt):
    return dict(e=e, x=x, y=y, en=en, pt=pt, say=say, sayPt=sayPt)


def G(q, pt, opts, a, why):
    return dict(q=q, pt=pt, opts=opts, a=a, why=why)


def T(opts, a, why, q='Qual frase está certa?'):
    return dict(q=q, opts=opts, a=a, why=why)


def EXP(ic, en, tag, pt, use, ex_en, ex_pt):
    return dict(ic=ic, en=en, tag=tag, pt=pt, use=use, ex=[ex_en, ex_pt])


def VBI(v, ic, pt, f1, f2, ex_en, ex_pt, note):
    return dict(v=v, ic=ic, pt=pt, f=[['eu', f1], ['ele/ela', f2]], ex=[ex_en, ex_pt], note=note)


def MOLD(label, *slots, end=('.', '.')):
    return dict(label=label, slots=[dict(cat=c, opts=[list(o) for o in os_]) for c, os_ in slots], end=list(end))


def DATA(prompt, ph, chips, model, check, kw, tips, ok, reply):
    return dict(prompt=prompt, ph=ph, chips=chips, model=model, check=check, kw=kw,
                tips=[[list(p) for p in t] for t in tips], ok=ok, reply=reply)


def MT(ask, opts, a, why, say=None):
    d = dict(ask=ask, opts=opts, a=a, why=why)
    if say:
        d['say'] = say
    return d


def MG(text, pt, opts, a, why, say):
    return dict(text=text, pt=pt, opts=opts, a=a, why=why, say=say)


def CXI(text, pt, opts):
    return dict(text=text, pt=pt, opts=opts, a=0)


def RND(say, opts, a, why):
    return dict(fig='🎧', say=say, ask='Qual palavra você ouviu?', opts=opts, a=a, why=why)


def HW(say, opts, a, why):
    return dict(fig='🎧', say=say, ask='Ouça e toque na palavra.', opts=opts, a=a, why=why)


def HP(say, opts, a, pt):
    return dict(fig='🎧', say=say, ask='Ouça e toque na figura.', opts=[[e, ''] for e in opts], a=a,
                why='**%s** = %s.' % (say, pt), pic=1)


KEYS = 'rdg pat vplay sbuild build order balloons dictate soundlab scene dquiz scenebuild produce review wrap'.split()


def RSD(*scenes):
    assert len(scenes) == 15
    return dict(zip(KEYS, scenes))


def LAB(short, title, say, what, how, pt, ex, pairs, tip, phrase, rounds):
    return dict(short=short, title=title, say=say, intro=dict(what=what, how=how, pt=pt), ex=[list(e) for e in ex],
                pairs=[list(p) for p in pairs], tip=tip, phrase=list(phrase), rounds=rounds)


def cover(s, a, b, c, seed):
    return dict(s=s, items=[[a, 104, 56, 20, 'bob'], [b, 138, 44, 12, 'bob'], [c, 84, 34, 12, 'bob']], seed=seed)


